def minOperations(nums1, nums2):
    n = len(nums1)

    def check(swap_last):
        # Values that must end up at the last position of nums1 and nums2
        if swap_last:
            t1, t2 = nums2[-1], nums1[-1]
            cnt = 1
        else:
            t1, t2 = nums1[-1], nums2[-1]
            cnt = 0

        for i in range(n - 1):
            x, y = nums1[i], nums2[i]
            if x <= t1 and y <= t2:
                continue                # fits without swapping
            if y <= t1 and x <= t2:
                cnt += 1                # fits after swapping index i
            else:
                return -1               # neither orientation works
        return cnt

    ans1 = check(False)
    ans2 = check(True)

    if ans1 == -1:
        return ans2
    if ans2 == -1:
        return ans1
    return min(ans1, ans2)
